# Generated by build.py from recipe.yml for recipe curl-check-many-urls-from-one-config. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'site/docs', 'broken', 'broken/docs' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/health.txt'), "ok`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/version.txt'), "1.4.2`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/docs/readme.txt'), "read me`n")
[IO.File]::WriteAllText((Join-Path $PWD 'broken/health.txt'), "ok`n")
[IO.File]::WriteAllText((Join-Path $PWD 'broken/docs/readme.txt'), "read me`n")
[IO.File]::WriteAllText((Join-Path $PWD 'urls.conf'), "# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Every URL the deployment must answer. The ports come from the command line:`n#   curl --variable http_port=<port> --variable ftp_port=<port> -K urls.conf`nfail`nsilent`nshow-error`nfail-early`nwrite-out = `"%{onerror}FAILED %{url}\n`"`n`nexpand-url = `"http://127.0.0.1:{{http_port}}/health.txt`"`nout-null`nexpand-url = `"http://127.0.0.1:{{http_port}}/version.txt`"`nout-null`nexpand-url = `"ftp://127.0.0.1:{{ftp_port}}/docs/readme.txt`"`nout-null`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'main.log', '--directory', 'site', '--allow-anonymous', 'http://127.0.0.1:8080/', 'ftp://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --variable http_port=8080 --variable ftp_port=8081 -K urls.conf } finally { Stop-Process $server0 }
